Here is the commit message:
ALSA: ac97: fix a double free in
 snd_ac97_controller_register()

If ac97_add_adapter() fails, put_device() is the correct way to drop
the device reference. kfree() is not required.
Add kfree() if idr_alloc() fails and in ac97_adapter_release() to do
the cleanup.

Found by code review.

Fixes: 74426fbff66e ("ALSA: ac97: add an ac97 bus")
Cc: stable@vger.kernel.org
Signed-off-by: Haoxiang Li <lihaoxiang@isrc.iscas.ac.cn>
Link: https://patch.msgid.link/20251219162845.657525-1-lihaoxiang@isrc.iscas.ac.cn
Signed-off-by: Takashi Iwai <tiwai@suse.de>

Here is the root cause:
The error handling in `snd_ac97_controller_register()` used a separate `kfree(ac97_ctrl)` in its error path after `ac97_add_adapter()` failed. However, `ac97_add_adapter()` already calls `put_device()` on failure (which triggers `ac97_adapter_release()`). The original release function did not free the controller structure, so the separate `kfree` was needed but violated the kernel device model. When the release function was later fixed to free the structure (as part of this patch), the separate `kfree` in the caller would cause a double free. Thus, the root cause is the improper use of a separate `kfree` instead of relying on the device release mechanism, leading to a double free when the release function is correctly implemented.

Here is the patch:

 static void ac97_adapter_release(struct device *dev)
 {
 	struct ac97_controller *ac97_ctrl;

 	ac97_ctrl = to_ac97_controller(dev);
 	idr_remove(&ac97_adapter_idr, ac97_ctrl->nr);
 	dev_dbg(&ac97_ctrl->adap, "adapter unregistered by %s\n",
 		dev_name(ac97_ctrl->parent));
+	kfree(ac97_ctrl);
 }


 static int ac97_add_adapter(struct ac97_controller *ac97_ctrl)
 {
 	int ret;

 	guard(mutex)(&ac97_controllers_mutex);
 	ret = idr_alloc(&ac97_adapter_idr, ac97_ctrl, 0, 0, GFP_KERNEL);
 	ac97_ctrl->nr = ret;
 	if (ret >= 0) {
 		dev_set_name(&ac97_ctrl->adap, "ac97-%d", ret);
 		ac97_ctrl->adap.type = &ac97_adapter_type;
 		ac97_ctrl->adap.parent = ac97_ctrl->parent;
 		ret = device_register(&ac97_ctrl->adap);
 		if (ret)
 			put_device(&ac97_ctrl->adap);
-	}
+	} else
+		kfree(ac97_ctrl);
+
 	if (!ret) {
 		list_add(&ac97_ctrl->controllers, &ac97_controllers);
 		dev_dbg(&ac97_ctrl->adap, "adapter registered by %s\n",
 			dev_name(ac97_ctrl->parent));
 	}
 	return ret;
 }

  */
 struct ac97_controller *snd_ac97_controller_register(
 	const struct ac97_controller_ops *ops, struct device *dev,
 	unsigned short slots_available, void **codecs_pdata)
 {
 	struct ac97_controller *ac97_ctrl;
 	int ret, i;

 	ac97_ctrl = kzalloc(sizeof(*ac97_ctrl), GFP_KERNEL);
 	if (!ac97_ctrl)
 		return ERR_PTR(-ENOMEM);

 	for (i = 0; i < AC97_BUS_MAX_CODECS && codecs_pdata; i++)
 		ac97_ctrl->codecs_pdata[i] = codecs_pdata[i];

 	ac97_ctrl->ops = ops;
 	ac97_ctrl->slots_available = slots_available;
 	ac97_ctrl->parent = dev;
 	ret = ac97_add_adapter(ac97_ctrl);

 	if (ret)
-		goto err;
+		return ERR_PTR(ret);
 	ac97_bus_reset(ac97_ctrl);
 	ac97_bus_scan(ac97_ctrl);

 	return ac97_ctrl;
-err:
-	kfree(ac97_ctrl);
-	return ERR_PTR(ret);
 }
 EXPORT_SYMBOL_GPL(snd_ac97_controller_register);


